def evaluate(current_reputation, observation, my_history, round_num):
    # Update reputation based on observed action
    if observation['action'] == 'cooperate':
        new_rep = current_reputation + 0.1
    else:
        new_rep = current_reputation - 0.2  # penalize defection more heavily
    # Clamp to valid range [-1.0, 1.0]
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
    # First 10 rounds: always cooperate (like the original)
    if round_num <= 10:
        return True
    # After round 10: cooperate if recipient reputation is high enough
    # Also adjust threshold based on own recent behavior
    recent_defections = sum(1 for act in my_history[-3:] if not act)
    # If we have defected often recently, be more cautious (require higher reputation)
    if recent_defections >= 2:
        threshold = 0.5
    else:
        threshold = -0.2
    return recipient_reputation > threshold
